    "text": "আজি, ৫০খন দেশৰ ২,১০০ৰো অধিক প্ৰত্যয়িত বি কৰ্পছ আৰু ১৩০টাতকৈও অধিক উদ্যোগৰ এক বৰ্ধিত সম্প্ৰদায় আছে যি ১টা একীকৰণমূলক লক্ষ্যৰ দিশে একেলগে কাম কৰি আছে: ব্যৱসায়ত সফলতাক পুনৰ সংজ্ঞায়িত কৰা। আন্দোলনত যোগদান কৰক",
