    "text": "উচ্চ ৰক্তচাপ (হাইপাৰটেনচন)ৰ উপশম - অধ্যয়নসমূহে দেখুৱাইছে যে পটাছিয়াম বেছি থকা আহাৰ, বিশেষকৈ ফল আৰু শাক-পাচলিৰ পৰা পটাছিয়াম থকা খাদ্যই ৰক্তচাপ কমায়। এইটো বিশেষভাৱে সত্য যদি পটাছিয়াম যুক্ত খাদ্যৰ বৃদ্ধিৰ সৈতে উচ্চ ছ'ডিয়াম যুক্ত খাদ্যৰ বৃদ্ধি নহয়।",
