    "id": "74ac1754758b6b621695",
    "text": "১ তেওঁৰ সততাক প্ৰশংসা কৰা উচিত। ২ আৰু কাহিনীটোৰ নৈতিকতা হৈছে যে সততা সদায় সৰ্বোত্তম নীতি। ৩ মোৰ তেওঁৰ সততাক সন্দেহ কৰাৰ কোনো কাৰণ নাই, ইয়াৰ কাৰণ হৈছে মই বুজি নাপাও যে ইয়াক কেনেকৈ ঘটিল।",
