    "text": "હાઈ બ્લડ પ્રેશર (હાયપરટેન્શન)નું ઉપશમન - અભ્યાસો દર્શાવે છે કે પોટેશિયમથી ભરપૂર આહાર, ખાસ કરીને ફળો અને શાકભાજીમાંથી પોટેશિયમ, લોહીનું દબાણ ઘટાડે છે. આ ખાસ કરીને સાચું છે જો પોટેશિયમ વાળા ખોરાકમાં વધારો સોડિયમ વાળા ખોરાકમાં વધારો સાથે ન હોય.",
