    "text": "તેની કિંમત કેટલી છે? તમે કેટલી આગળ વધુ આગાહી કરો છો અને ટ્રેન કેટલી ભરેલી છે તેના આધારે તેની કિંમત 50.00 ડોલરથી 98.00 ડોલર સુધીની હોય છે. કિંમત માહિતી માટે અમટ્રેકનો સંપર્ક કરો; હાર્ટલેન્ડ ફ્લાયર વેબસાઇટ પર કિંમતો ઉપલબ્ધ નથી.",
