    "id": "f303fe8ac716c16619e9",
    "text": "सोडियम कमी पोटॅशियम असलेल्या खाद्यपदार्थांची यादी. या पृष्ठावर आम्ही निरोगी आहारासाठी हजारो खाद्यपदार्थांवरील पोषणमूल्याची शोधण्यायोग्य माहिती देतो. निरोगी खाणे केवळ वजन कमी करण्यासाठीच फायदेशीर नाही तर तुमचे आरोग्य सुधारण्यासाठी देखील फायदेशीर ठरेल.",
