    "id": "e4eb5fc6244deb79a147",
    "text": "रक्तदाबाचा उच्चांक (हायपरटेन्शन) - अभ्यास दर्शवतात की पोटॅशियमचा आहार, विशेषत: फळे आणि भाज्यांमधील पोटॅशियम, रक्तदाब कमी करतो. हे विशेषतः खरे आहे जर पोटॅशियम असलेल्या पदार्थांमधील वाढ सोडियम असलेल्या पदार्थांच्या वाढीसह नसेल.",
