    "id": "2b8638d56e4aef93274f",
    "text": "बिल्ज - खालच्या आणि बाजूच्या बाजूंमधील वक्राकार विभाग; ज्यामध्ये सर्व पाणी वाहते. बिल्ज ब्लॉक्स - बांधकाम किंवा ड्रायडॉकिंग दरम्यान आधारासाठी वापरले जाणारे आधार देणारे ब्लॉक. बिल्ज ब्लॉक्स ड्रायडॉकवर जहाजाला आधार देणारे ब्लॉक.",
