    "text": "स्ट्रुथर्स हायस्कूल सिनियर्स - नवीन $८,००० शिष्यवृत्तीसाठी अर्ज करा स्ट्रुथर्स हायस्कूलच्या मार्गदर्शन विभागातील एका पदवीधर वरिष्ठासाठी नवीन $८,००० शिष्यवृत्ती उपलब्ध आहे. ओटिस आर. हेल्डमन सीनियर आणि ज्युनियर स्कॉलर-अ‍ॅथलीट पुरस्कार आणि शिष्यवृत्ती चार वर्षांतील शैक्षणिक आणि क्रीडा या दोन्ही क्षेत्रातील कामगिरीची ओळख देते.",
