    "text": "जगभरात लोकसंख्या सात अब्ज आहे. २०५० पर्यंत अमेरिकेतील लोकसंख्या ४०० दशलक्षांवर पोहोचेल असा अंदाज आहे - सुमारे ४० वर्षांत ३३ टक्के वाढ; २००६ मध्ये अमेरिकेने ३०० दशलक्षव्या रहिवाश्याला नोंदणी केली. जागतिक लोकसंख्येत वाढ झाल्याने वायू प्रदूषणात वाढ झाली आहे.",
