    "text": "द्रुत उत्तर. गरुड ३० ते ५५ मैल प्रति तास वेगाने उडतात आणि १०० मैल प्रति तासापेक्षा जास्त वेगाने सूर मारतात. गरुड उष्ण हवेच्या प्रवाहांवर तासांच्या तासांसाठी उडू शकतात, ज्यामुळे ऊर्जेची बचत होते, विशेषत: लांब स्थलांतरांच्या वेळी.",
