    "text": "त्यासाठी किती खर्च येईल? तुम्ही आरक्षण किती पुढे करता आणि रेल्वे किती भरलेली आहे यावर अवलंबून त्याची किंमत $५०.०० ते $९८.०० पर्यंत असते. किंमतीची माहिती अमट्रॅकशी संपर्क साधा; हार्टलँड फ्लायर संकेतस्थळावर किंमती उपलब्ध नाहीत.",
