    "text": "फोन कॉन्टॅक्ट नंबर्स. १ यूएस आणि कॅनडा: १-८६६-७८८-२४८२. २ ऑस्ट्रेलिया: १-८००-९१०-९२१. ३ फ्रान्स: ०८००-९१९-२७८. ४ जर्मनी: ०८००-१८१-१०-७७. ५ मेक्सिको: ००१-८००-५१४-८१७५. ६ युनायटेड किंगडम: ०८००-३५८-८५८५. ७ इतर देश: १-४१५-२२२-८४००.",
