    "text": "आज, ५० देशहरूबाट २,१०० भन्दा बढी प्रमाणित बी कोरको बढ्दो समुदाय छ र १३० भन्दा बढी उद्योगहरू एकीकृत लक्ष्यतिर काम गरिरहेका छन्: व्यवसायमा सफलतालाई पुन: परिभाषित गर्न। आन्दोलनमा सामेल हुन",
