    "text": "स्ट्रुथर्स हाई स्कुल सिनियर्स - नयाँ $८,००० छात्रवृत्तिका लागि आवेदन दिनुहोस् स्ट्रुथर्स हाई स्कुलको मार्गदर्शन विभागले एक स्नातक वरिष्ठका लागि उपलब्ध नयाँ $८,००० छात्रवृत्ति घोषणा गर्दछ। ओटिस आर हेल्डम्यान सिनियर र जुनियर स्कोलर-एथलिट अवार्ड र छात्रवृत्तिले चार वर्षमा शैक्षिक र खेलकुद दुवैमा उपलब्धिको मान्यता दिन्छ।",
