    "text": "विश्वव्यापी रूपमा, जनसङ्ख्या सात अरब छ। अनुमान छ कि संयुक्त राज्य अमेरिकाको जनसङ्ख्या सन् २०५० सम्म ४०० मिलियन पुग्नेछ - लगभग ४० वर्षको अवधिमा ३३ प्रतिशत वृद्धि; अमेरिकाले सन् २००६ मा आफ्नो ३०० मिलियनमा दर्ता गरेको थियो। विश्वको जनसङ्ख्या वृद्धिसँगै वायु प्रदूषणमा वृद्धि आएको छ।",
