    "text": "२० वर्षमा पहिलो पटक, एनएचएलको प्लेअफ ढाँचा मुख्यतया डिभिजनहरूमा आधारित छ, सम्मेलनहरूमा होइन। अब १ बनाम ८, २ बनाम ७, आदि छैन। परिवर्तन गाह्रो छ, र निश्चित छ, नयाँ तरिका अलिक जटिल छ।",
