    "text": "दाँतको मुकुटलाई पुन: स्थापित गर्न कति खर्च लाग्छ? सार्लोट, एनसीमा मुकुट लगाएको दाँतलाई पुन: स्थापित गर्न लगभग कति खर्च लाग्छ? हो, मैले लगभग १० वर्षअघि अगाडि दाँतलाई मुकुटले बदलेको थिएँ अनि अहिले यो फेसबुकमा ढिलो पोस्ट गरिएको छ।",
