    "id": "956132b051b4fc79641a",
    "text": "गोल्ड क्राउन लागत। दन्त क्राउनको लागत सारांश दन्त क्राउनको मूल्य प्रति क्राउन $ ५०० देखि $ २,५०० सम्म हुन्छ र यो प्रयोग गरिएको सामग्री, दाँतको स्थान र भौगोलिक स्थानमा निर्भर गर्दछ। क्राउनको औसत लागत $ ८२५ हो, दन्त बिमा कभरेजको साथ वा बिना। दन्त क्राउनको सस्तो लागत एक साधारण धातुको क्राउनका लागि $ ५०० हो। दन्त क्राउन विशेष रूपमा आकार दिएका खोलहरू हुन् जुन कस्मेटिक वा संरचनात्मक उद्देश्यका लागि क्षतिग्रस्त वा टुटेका दाँतहरूमा फिट हुन्छन्।",
