    "id": "36b7b92e9339c8a052b3",
    "text": "एक किलोवाट-घन्टा (१ किलोवाट-घन्टा) को अर्थ एक ऊर्जा स्रोतले एक घन्टाका लागि १,००० वाट (१ किलोवाट) ऊर्जा आपूर्ति गर्दछ। सामान्यतया, एक सौर ऊर्जा प्रणालीले दिनमा लगभग ५ घन्टाका लागि आउटपुट प्रदान गर्दछ। त्यसैले, यदि तपाईँसँग १.८ किलोवाट प्रणालीको आकार छ र यसले दिनमा ५ घन्टाका लागि उत्पादन गर्दछ, वर्षमा ३६५ दिन: यो सौर ऊर्जा प्रणालीले वर्षमा ३,२८५ किलोवाट-घन्टा (१.८ किलोवाट x ५ घन्टा x ३६५ दिन) उत्पादन गर्नेछ। यदि पिभी प्यानलहरू दिनको भागका लागि छायाङ्कन गरिएको छ भने, आउटपुट छायाङ्कन प्रतिशत अनुसार कम हुनेछ।",
