    "text": "१००/१००० (किलोवाट) x १० (घन्टा) x ३० दिन = ३० किलोवाट प्रति महिना सौर्य प्यानलहरू जहाँ पनि काम गर्नेछन् जहाँ सूर्य छ; यद्यपि, केही स्थानहरू अरू भन्दा राम्रा छन्। यहाँ केही महत्त्वपूर्ण कारकहरू छन् जसलाई तपाईँले ध्यानमा राख्न आवश्यक छ: स्थान। दक्षिणी स्थानहरूले उत्तरी स्थानहरू भन्दा बढी प्रत्यक्ष सूर्यको प्रकाश प्राप्त गर्छन्।",
