    "text": "କମ ସୋଡିୟମ କମ ପୋଟାସିୟମ ଖାଦ୍ୟ ତାଲିକା। ଏହି ପୃଷ୍ଠାରେ ଆମେ ସ୍ୱାସ୍ଥ୍ୟକର ଖାଦ୍ୟ ପାଇଁ ହଜାର ହଜାର ଖାଦ୍ୟ ଉପରେ ପୋଷକ ତଥ୍ୟର ଏକ ସନ୍ଧାନଯୋଗ୍ୟ ସଂଗ୍ରହ ପ୍ରଦାନ କରୁଛୁ। ସ୍ୱାସ୍ଥ୍ୟକର ଖାଦ୍ୟ କେବଳ ଓଜନ ହ୍ରାସ ପାଇଁ ଉପଯୋଗୀ ନୁହେଁ, ବରଂ ଆପଣଙ୍କ ସ୍ୱାସ୍ଥ୍ୟକୁ ମଧ୍ୟ ଉନ୍ନତ କରିବ।",
