    "id": "b6a15eb4aa45764b30f0",
    "text": "ଉଚ୍ଚ ରକ୍ତଚାପ (ହାଇପର୍‍‌ଟେନ୍‍‌ସନ) ରୋଗ ଉପଶମ - ଅଧ୍ୟୟନରୁ ଜଣାପଡ଼ିଛି ଯେ ପୋଟାସିୟମ ଯୁକ୍ତ ଖାଦ୍ୟ, ବିଶେଷ କରି ଫଳ ଏବଂ ପନିପରିବାରୁ ପୋଟାସିୟମ, ରକ୍ତଚାପ କମାଇଥାଏ। ଏହା ବିଶେଷ କରି ସତ ଯଦି ପୋଟାସିୟମ ଯୁକ୍ତ ଖାଦ୍ୟ ଖାଦ୍ୟ ପଦାର୍ଥର ବୃଦ୍ଧି ସହିତ ଉଚ୍ଚ ସୋଡିୟମ ଯୁକ୍ତ ଖାଦ୍ୟ ପଦାର୍ଥର ବୃଦ୍ଧି ନ ହୁଏ।",
