    "id": "2478d3573203e2883c5d",
    "text": "ଶିପ୍‌ଡ ମାଧ୍ୟମରେ ନିୟମିତ ଭାବେ ଉପସ୍ଥିତ ହେଉଥିବା ଉତ୍ତମ ସୁଯୋଗଗୁଡିକର ଲାଭ ନିଅନ୍ତୁ। ଫ୍ଲାଟ ବଟମ ଟ୍ୟାଙ୍କର ବ୍ୟତୀତ ଆପଣ ନଦୀ ବାର୍ଜ, ଫେରୀ, ଟ୍ୟାଙ୍କର, ରାସାୟନିକ ତେଲ ଟ୍ୟାଙ୍କର କିମ୍ବା ଶୁଖିଲା କାର୍ଗୋ ଜାହାଜ ଆଦି ପାଇବେ। ପ୍ରଥମ ଜାଣନ୍ତୁ ଯେ ନୂତନ ଫ୍ଲାଟ ବଟମ ଟ୍ୟାଙ୍କର ଆମ ଷ୍ଟକରେ ପ୍ରବେଶ କରିଛି। ଆମ ମେଲିଂ ତାଲିକାରେ ନିଜକୁ ସବସ୍କ୍ରାଇବ କରନ୍ତୁ ଯାହା ଫଳରେ ଆମ ନୂତନ ଆଗମନ ବିଷୟରେ ଆପଣଙ୍କୁ ଜଣାଇ ଦିଆଯିବ। ଶିପ୍‌ଡ 1984 ମସିହାରୁ ଏକ ଆନ୍ତର୍ଜାତୀୟ ଜାହାଜ ବ୍ୟବସାୟୀ ଭାବେ ସକ୍ରିୟ ରହିଛି, ଯାହା ନଦୀ ଏବଂ ସମୁଦ୍ର ଜାହାଜ ତଥା ଅନ୍ୟ ସାମୁଦ୍ରିକ ପ୍ରକଳ୍ପ ଯେମିତି କି ନୌକା ଆଦି ପ୍ରଦାନ କରି ଆସୁଛି।",
