    "id": "ab4e5d808ccd9cf9bc63",
    "text": "ବିଲ୍‌ଜେ- ଏକ ଜାହାଜର ତଳ ଏବଂ ପାର୍ଶ୍ୱ ମଧ୍ୟରେ ଏକ ବକ୍ର ଅଂଶ; ସମସ୍ତ ଜଳ ନିଷ୍କାସନ କରୁଥିବା ଏକ ଅବକ୍ଷେପଣ କରିଥିବା ଅଂଶ। ବିଲ୍‌ଜେ ବ୍ଲକ୍‌ସ - ନିର୍ମାଣ କିମ୍ବା ଡ୍ରାଇଡକିଂ ସମୟରେ ସମର୍ଥନ ପାଇଁ ବ୍ୟବହୃତ ସହାୟକ ବ୍ଲକ୍‌ସ। ବିଲ୍‌ଜେ ବ୍ଲକ୍‌ସ ଡ୍ରାଇଡକ୍‌ରେ ଏକ ଜାହାଜକୁ ସମର୍ଥନ କରୁଥିବା ବ୍ଲକ୍‌ସ।",
