    "id": "ced1ed02d6bdd6c64f88",
    "text": "ସତତା ହେଉଛି ଆଚରଣ ବିଷୟରେ; ସତ୍ୟତା ହେଉଛି ତଥ୍ୟ ପ୍ରତି ଅନୁଗତ ରହିବା ବିଷୟରେ। ଯେ ବ୍ୟକ୍ତି ପ୍ରତି ସପ୍ତାହରେ ତାଙ୍କ ଟାଇମ୍‌ସିଟ୍ ଜମା କରି କିଛି ସମୟ ନେଇ ଅନିଶ୍ଚିତ ଥିଲେ ସ୍ପଷ୍ଟୀକରଣ ଚାହିଁ ଆସେ, ସେ ସତତା ସହ କାର୍ଯ୍ୟ କରୁଛନ୍ତି। ସେ ସମ୍ଭବତ ସତତା ସହ ମଧ୍ୟ କାର୍ଯ୍ୟ କରୁଛନ୍ତି, ଯାହା ଫଳରେ ସେ ରିପୋର୍ଟ କରୁଥିବା ସଂଖ୍ୟା ସଠିକ ଅଟେ ତାହା ସୁନିଶ୍ଚିତ କରୁଛନ୍ତି।",
