    "id": "ff58d62aa2b59ebe1b40",
    "text": "1. ତାଙ୍କ ସତ୍ୟତା ପାଇଁ ତାଙ୍କୁ ପ୍ରଶଂସା କରାଯିବା ଉଚିତ। 2. ଏବଂ କାହାଣୀର ନୈତିକ ଶିକ୍ଷା ହେଉଛି ଯେ ସତ୍ୟତା ସର୍ବଦା ସର୍ବୋତ୍ତମ ନୀତି। 3. ମୋର ତାଙ୍କ ସତ୍ୟତା ଉପରେ ସନ୍ଦେହ କରିବାର କୌଣସି କାରଣ ନାହିଁ, ଏହା କେବଳ ମୁଁ ଏହା କିଭଳି ଘଟିଲା ତାହା ବୁଝି ପାରୁନି।",
