    "id": "ce9a3d1013ed186d1e01",
    "text": "ସେଭ ସ୍କୁଲ. 1 ଷ୍ଟ୍ରୁଥର୍ସ ପ୍ରାଥମିକ ବିଦ୍ୟାଳୟ ପିକେ-4 ଶ୍ରେଣୀର 697 ଛାତ୍ରଛାତ୍ରୀଙ୍କୁ ସେବା ପ୍ରଦାନ କରେ। 2 ସଂଖ୍ୟାଲଘୁ ଛାତ୍ର ଛାତ୍ରୀ ଗୋଷ୍ଠୀର 20% (ଅଧିକାଂଶ ହିସ୍ପାନିକ) ରହିଛି, ଯାହା ରାଜ୍ୟ ହାର 28% ତୁଳନାରେ କମ। 3 ଷ୍ଟ୍ରୁଥର୍ସ ପ୍ରାଥମିକ ବିଦ୍ୟାଳୟ ଷ୍ଟ୍ରୁଥର୍ସ ସିଟି ସ୍କୁଲ ଜିଲ୍ଲା ମଧ୍ୟରେ କାର୍ଯ କରେ। ସ୍କୁଲ ଓଭରଭିୟୁ ଛାତ୍ର ଜନସଂଖ୍ୟା 697 ଛାତ୍ର ଛାତ୍ରୀ ପାଞ୍ଚ ବର୍ଷ ଧରି ତୁଳନାତ୍ମକ ଭାବେ ସ୍ଥିର ରହିଛି।",
