    "text": "ଓଣ୍ଟାରିଓ, କାନାଡାର ନୂତନ ଗବେଷଣା ପୋଷ୍ଟ-ଟ୍ରମାଟିକ ଷ୍ଟ୍ରେସ ଡିସଅର୍ଡର ରୋଗୀଙ୍କୁ କାନାବିସ କିପରି ସାହାଯ୍ୟ କରେ ସେ ସମ୍ପର୍କରେ କିଛି ରୋଚକ ତଥ୍ୟ ଉଦ୍‌ଘାଟନ କରିଛି। ଏହି ନୂତନ ଅଗ୍ରଗତି କାହିଁକି ଆମେରିକାର ଅନେକ ପୁରୁଖା ନିବୃତ୍ତ ଚିକିତ୍ସକ ତାଙ୍କ ମାନସିକ ଔଷଧ ପରିତ୍ୟାଗ କରି କାନାବିସ ଆଡ଼କୁ ମୁହାଁଇଛନ୍ତି ତାହା ବୁଝାଇବାରେ ସାହାଯ୍ୟ କରେ।",
