    "text": "ପ୍ରକ୍ଷେପଣ ହେଉଛି ଯେ ଯୁକ୍ତରାଷ୍ଟ୍ର ଆମେରିକାର ଜନସଂଖ୍ୟା ୨୦୫୦ ସୁଦ୍ଧା ୪୦୦ ନିୟୁତ ପର୍ଯ୍ୟନ୍ତ ପହଞ୍ଚିବ – ପ୍ରାୟ ୪୦ ବର୍ଷ ମଧ୍ୟରେ ୩୩ ପ୍ରତିଶତ ବୃଦ୍ଧି; ୨୦୦୬ ମସିହାରେ ଆମେରିକା ତା'ର ୩୦୦ ନିୟୁତ ନିବାସୀ ପଞ୍ଜୀକୃତ କରିଥିଲା। ବିଶ୍ୱ ଜନସଂଖ୍ୟା ବୃଦ୍ଧି ସହିତ ବାୟୁ ପ୍ରଦୂଷଣ ବୃଦ୍ଧି ପାଇଛି।",
