    "text": "ଏନ.ଏଚ.ଏଲ.କୁ 2ଟି କନଫରେନ୍ସରେ ଏବଂ ତା'ପରେ ପ୍ରତି କନଫରେନ୍ସରେ 3ଟି ଡିଭିଜନରେ ବିଭକ୍ତ କରାଯାଇଛି। ପ୍ରତି ଡିଭିଜନରେ ସର୍ବାଧିକ ପଏଣ୍ଟ ଥିବା ଦଳଗୁଡ଼ିକ 1-3 ସିଡ୍ ଏବଂ ପରବର୍ତ୍ତୀ ସର୍ବୋଚ୍ଚ ଦଳଗୁଡ଼ିକ 4-8 ସିଡ୍ ପାଇଥାନ୍ତି। 16ଟି ଦଳ ପ୍ଲେ-ଅଫରେ ପ୍ରବେଶ କରନ୍ତି ଏବଂ ପ୍ରତି ରାଉଣ୍ଡ 7 ଟି ଶ୍ରେଣୀ ମଧ୍ୟରେ ହୋଇଥାଏ। ରାଉଣ୍ଡ 1 (କ୍ୱାର୍ଟର ଫାଇନାଲ): 16 ଟି ଦଳ (ପ୍ରତି କନଫରେନ୍ସ 8)। 1 vs 8, 2 vs 7, 3 vs 6, 4 vs 5। ସିଡ୍ 1-4 ହୋମ ଆଇସ ଆଡଭାନ୍ଟେଜ *।",
