    "text": "ଚର୍ମର ରିଙ୍ଗୱର୍ମ (ଟିନିଆ କର୍ପୋରିସ) ସାଧାରଣତଃ ଫଙ୍ଗସ ଟ୍ରାଇକୋଫାଇଟନ ରୁବ୍ରମ ଦ୍ୱାରା ହୋଇଥାଏ, ଯାହା ଜଣେ ବ୍ୟକ୍ତିଠାରୁ ଅନ୍ୟ ଜଣକୁ ବ୍ୟାପିଥାଏ। ଏହା ମାଇକ୍ରୋସ୍ପୋରମ କାନିସ ଦ୍ୱାରା ମଧ୍ୟ ହୋଇପାରେ, ଯାହା ବିଲେଇ ଏବଂ କୁକୁର ଦ୍ୱାରା ବ୍ୟାପିଥାଏ। ଏହି ପ୍ରକାର କମ ସାଧାରଣ କିନ୍ତୁ ଅଧିକ ଗୁରୁତର ସଂକ୍ରମଣ କରିଥାଏ।",
