    "text": "ରିଙ୍ଗୱର୍ମ କ'ଣ କାରଣରୁ ହୁଏ? ରିଙ୍ଗୱର୍ମ କୃମି ଦ୍ୱାରା ହୁଏ ନାହିଁ। ଚର୍ମ ସଂକ୍ରମଣ, ଯାହାକୁ ଟିନିଆ ମଧ୍ୟ କୁହାଯାଏ, ଡର୍ମାଟୋଫାଇଟ ନାମକ କବକ ଦ୍ୱାରା ହୁଏ। କବକ ହେଉଛି ଅଣୁଜୀବ ଯାହା ତ୍ୱଚା, କେଶ ଏବଂ ନଖ ଉପରେ ମୃତ ଟିସୁ ଉପରେ ବଞ୍ଚି ରହି ପାରେ, ଠିକ ଯେମିତି ଏକ ଛତୁ ଗଛ ଛାଲ ଉପରେ ବଢ଼ି ପାରେ। ରିଙ୍ଗୱର୍ମ ଏକ କବକ ଦ୍ୱାରା ହୁଏ ଯାହା ତ୍ୱଚା ଉପରେ ବଢ଼େ।",
