    "id": "2949c34c3e8a86d65a7e",
    "text": "ଏକ କିଲୋୱାଟ-ଘଣ୍ଟା (1 କି.ୱା.) ଅର୍ଥ ହେଉଛି ଏକ ଶକ୍ତି ଉତ୍ସ ଏକ ଘଣ୍ଟା ପାଇଁ 1,000 ୱାଟ (1 କି.ୱା.) ଶକ୍ତି ଯୋଗାଇ ଥାଏ। ସାଧାରଣତଃ, ଏକ ସୌର ଶକ୍ତି ବ୍ୟବସ୍ଥା ଦିନକୁ ପ୍ରାୟ 5 ଘଣ୍ଟା ପାଇଁ ଆଉଟପୁଟ ପ୍ରଦାନ କରିଥାଏ। ତେଣୁ, ଯଦି ଆପଣା ପାସରେ 1.8 କି.ୱା. ସିଷ୍ଟମ ଆକାର ଥାଏ ଏବଂ ଏହା ଦିନକୁ 5 ଘଣ୍ଟା ପାଇଁ ଉତ୍ପାଦନ କରେ, ବର୍ଷକୁ 365 ଦିନ: ଏହି ସୌର ଶକ୍ତି ବ୍ୟବସ୍ଥା ବର୍ଷକୁ 3,285 କି.ୱା. (1.8 କି.ୱା. x 5 ଘଣ୍ଟା x 365 ଦିନ) ଉତ୍ପାଦନ କରିବ। ଯଦି ପି.ଭି. ପ୍ୟାନେଲ ଦିନର କିଛି ଅଂଶ ପାଇଁ ଛାୟା ପଡ଼େ, ତାହେଲେ ଛାୟା ଶତାଂଶ ଅନୁଯାୟୀ ଆଉଟପୁଟ ହ୍ରାସ ପାଇବ।",
