    "text": "रक्तचापस्य उच्चीकरणम् (हैपर्टेन्शन्) - अध्ययनानि दर्शयन्ति यत् पोटेशियम् इत्यस्य अधिकमात्रायां आहारे, विशेषतः फलानां, शाकानां च पोटेशियम् इत्यस्य आधारेण रक्तचापः न्यूनीभवति। यदि पोटेशियम्-युक्तानां खाद्यपदार्थानां वृद्धिः सोडियं-युक्तानां खाद्यपदार्थानां वृद्ध्या सह न भवति तर्हि एतत् विशेषतः सत्यम् अस्ति।",
