    "id": "ce59d8eedb20e48af571",
    "text": "यदा वायोः भारः वर्धते तदा पारदः उच्चतरं भवति। यदा वायोः भारः न्यूनं भवति तदा पारदः न्यूनतरं भवति। वायुमण्डलीयः भारः मिलिबार् (एम्.बी.) मध्ये अपि मापयितुं शक्यते, यत्र एकः बार् प्रायः एकस्य वायुमण्डलीय-भारस्य (एकः वायुमण्डलः १.०१३२५ बार् इत्यस्य समानः) समानः भवति। एकः बार् २९.६ इञ्च्.एच्.जी. इत्यस्य समानः भवति। एच्.जी. बारोमीटर् इत्यस्य ३० इञ्च्. (एच्.जी.) मानं सामान्यम् इति मन्यते।",
