    "text": "तृतीयं नेब्रास्का-राज्यस्य लिङ्कन्-नगरस्य समीपे ब्लफ़्-रोड्-ल्याण्ड्फ़िल् इत्यत्र मिथेन्-उत्सर्जनं मापितम्, चतुर्थं च अहं कांश्चन परिणामान् प्रस्तौति, तथा च कथं प्रणोदन-परिवर्तनेन मिथेन्-उत्सर्जनं नियन्त्रितं भवति इति दर्शयितुं च, अन्ते अहं अस्माकं परिणामेभ्यः कांश्चन निष्कर्षान् चर्चां करिष्यामि।",
