    "text": "ओण्टारियो-केनडा-देशस्य नूतनसंशोधनेन, भूतकालस्य आघातोत्तर-मानसिक-सम्बन्धि-विकारेण पीडितानां कृते केनबस् इत्यस्य उपयोगः कथं भवति इति विषये केचन रोचकाः निष्कर्षाः प्राप्ताः। एतेषु अद्यतनेषु विकासेषु यत् अमेरिकादेशे बहवः वयोवृद्धाः स्वेषां मनोवैद्यकीय-औषधानि परित्यज्य केनबस्-औषधं स्व्यकुर्वन् इति व्याख्यातुं साहाय्यं भवति।",
