    "text": "विश्वे जनसङ्ख्या सप्त शतकोटिः अस्ति। पूर्वानुमानानुसारं २०५० तमवर्षपर्यन्तं संयुक्तराज्यामेरिकादेशस्य जनसङ्ख्या ४०० दशलक्षं यावत् भविष्यति - प्रायः ४० वर्षेषु ३३ प्रतिशतं वृद्धिः; २००६ तमे वर्षे अमेरिकादेशे ३०० दशलक्षं निवासिनः पञ्जीकृताः। विश्वस्य जनसङ्ख्यावृद्ध्या वायुप्रदूषणे वृद्धिः अभवत्।",
