    "text": "ایک کمپنی ایک مخصوص ملک میں شامل کی جاتی ہے، اکثر اس ملک کے ایک چھوٹے ذیلی سیٹ کی حدود کے اندر، جیسے ریاست یا صوبہ۔ کارپوریشن کو پھر اس ریاست میں شامل کرنے کے قوانین کے تحت چلایا جاتا ہے۔ ایک کارپوریشن اسٹاک جاری کر سکتی ہے، یا تو نجی یا عوامی، یا اسے غیر اسٹاک کارپوریشن کے طور پر درجہ بندی کیا جا سکتا ہے۔ اگر اسٹاک جاری کیا جاتا ہے، تو کارپوریشن عام طور پر اپنے شیئر ہولڈرز کے ذریعہ براہ راست یا بالواسطہ طور پر چلائی جائے گی۔",
