    "text": "کارسن نے اس کی تحریر کو صرف صحیح تحریری تکنیک میں آہستہ سے موخر کرتا ہے تاکہ یہ اندرونی انداز میں بے قابو نہ ہو جس سے قارئین کی دلچسپی پیدا ہوتی ہے۔ ریچل کارسن کی مخالفت کو بہت اچھی طرح سے نظر انداز کرتا ہے: \"THE OBLIGATION TO ENDURE\"۔ اسے آسان اور معلوماتی اور قائل کرنے والا رکھ کر اور اسے کسی غلط فہمی میں پھنسنے سے دور رکھ کر جو اس کے نقطہ نظر کو درست ثابت کرنے میں موثر ثابت ہوتا ہے۔",
