    "text": "شپڈ کے ذریعے باقاعدگی سے پیش آنے والے عظیم مواقع سے فائدہ اٹھائیں۔ فلیٹ بوٹم ٹینکرز کے علاوہ آپ کو دریا کے جہازوں سے لے کر فیری، ٹینکر، کیمیکل آئل ٹینکر، یا خشک کارگو جہاز تک کچھ بھی ملے گا۔ پہلے معلوم ہونے والے بنیں۔ پہلے معلوم ہونے والے بنیں جب نئے فلیٹ بوٹم ٹینکر ہمارے اسٹاک میں داخل ہوتے ہیں۔ اپنے آپ کو ہماری میلنگ لسٹ میں سبسکرائب کریں تاکہ آپ کو ہمارے نئے آنے والوں کے بارے میں مطلع کیا جائے۔ شپڈ 1984 سے ایک بین الاقوامی جہاز تاجر کے طور پر سرگرم ہے، جو دریا اور سمندری جہازوں اور دیگر سمندری منصوبوں جیسے کہ کشتیوں کی پیشکش کرتا ہے۔",
