    "text": "1 ان کی دیانتداری کے لیے ان کی تعریف کی جانی چاہیے۔ 2 اور کہانی کا اخلاقی سبق یہ ہے کہ دیانتداری ہمیشہ بہترین پالیسی ہوتی ہے۔ 3 مجھے ان کی دیانتداری پر شک کرنے کی کوئی وجہ نہیں ہے، یہ صرف یہ ہے کہ میں سمجھ نہیں سکتا کہ یہ کیسے ہوا۔",
