    "text": "جب ہوا کا دباؤ بڑھتا ہے، تو یہ پارے کو اوپر دھکیلتا ہے۔ جب ہوا کا دباؤ گرتا ہے، تو پارے کا درجہ بھی گرتا ہے۔ ماحولیاتی دباؤ کو ملی بار (ایم بی) میں بھی ماپا جا سکتا ہے، جہاں ایک بار تقریباً ایک ماحول کے دباؤ کے برابر ہوتا ہے (ایک ماحول 1.01325 بار کے برابر ہوتا ہے)۔ ایک بار 29.6 انچ کے برابر ہوتا ہے۔ ایچ جی بارومیٹر کی 30 انچ (ایچ جی) کی پڑھائی کو معمول سمجھا جاتا ہے۔",
